<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    PermissionModeDefault</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">     PermissionMode</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> iota</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 危险操作触发审批对话框</span></span>
